import { initScreenshotListener } from './screenshot';

export function initVly() {
  // This package is injected only into preview apps by vlyPlugin(). Preview
  // hostnames belong to the sandbox provider (for example Daytona or
  // WebContainer), so an application-domain allowlist would skip the listener
  // in the exact iframe that needs to answer screenshot requests.
  initScreenshotListener();
}

// Auto-initialize on import
if (typeof window !== 'undefined') {
  // Wait for DOM to be ready
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initVly);
  } else {
    initVly();
  }
}

export { initScreenshotListener } from './screenshot';
export type { ScreenshotMessage } from './screenshot';
