export interface ScreenshotMessage {
  type: 'vly-screenshot-request' | 'vly-screenshot-response' | 'vly-screenshot-error';
  requestId?: string;
  dataUrl?: string;
  error?: string;
  format?: 'png' | 'jpeg' | 'webp';
  quality?: number;
}

const CAPTURE_DELAY_MS = 2000;
const HTML2CANVAS_SRC =
  'https://cdn.jsdelivr.net/npm/html2canvas-pro@2.0.4/dist/html2canvas-pro.min.js';
const HTML2CANVAS_TIMEOUT_MS = 20000;

type Html2Canvas = (
  element: HTMLElement,
  options: Record<string, unknown>,
) => Promise<HTMLCanvasElement>;

let html2canvasLoadPromise: Promise<Html2Canvas> | null = null;
let screenshotListenerInitialized = false;

function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function loadHtml2Canvas(): Promise<Html2Canvas> {
  const existing = (window as Window & { html2canvas?: Html2Canvas }).html2canvas;
  if (existing) return Promise.resolve(existing);
  if (html2canvasLoadPromise) return html2canvasLoadPromise;

  html2canvasLoadPromise = new Promise<Html2Canvas>((resolve, reject) => {
    let script = document.querySelector<HTMLScriptElement>(
      'script[data-vly-screenshot-library]',
    );

    if (!script) {
      script = document.createElement('script');
      script.src = HTML2CANVAS_SRC;
      script.async = true;
      script.dataset.vlyScreenshotLibrary = 'true';
      document.head.appendChild(script);
    }

    const startedAt = Date.now();
    const poll = window.setInterval(() => {
      const runtime = (
        window as Window & { html2canvas?: Html2Canvas }
      ).html2canvas;

      if (runtime) {
        window.clearInterval(poll);
        resolve(runtime);
        return;
      }

      if (Date.now() - startedAt >= HTML2CANVAS_TIMEOUT_MS) {
        window.clearInterval(poll);
        if (script?.dataset.vlyScreenshotLibrary) {
          script.remove();
        }
        reject(new Error('Screenshot library did not finish loading'));
      }
    }, 100);
  }).catch((error) => {
    html2canvasLoadPromise = null;
    throw error;
  });

  return html2canvasLoadPromise;
}

export function initScreenshotListener() {
  if (screenshotListenerInitialized) return;
  screenshotListenerInitialized = true;
  // Start loading immediately, while still keeping request handling resilient
  // if the first capture arrives before the script has finished.
  void loadHtml2Canvas().catch((error) => {
    console.warn('[VLY Screenshot] Failed to preload screenshot library', error);
  });

  // Listen for screenshot requests from parent
  window.addEventListener('message', async (event) => {
    const message = event.data as ScreenshotMessage;

    if (message.type !== 'vly-screenshot-request') return;

    try {
      // The parent can request a screenshot shortly after the iframe loads.
      // Wait for the CDN library instead of failing the first attempt.
      const html2canvas = await loadHtml2Canvas();
      await delay(CAPTURE_DELAY_MS);

      // Capture screenshot
      const canvas = await html2canvas(document.body, {
        useCORS: true,
        allowTaint: false,
        backgroundColor: '#ffffff',
        logging: false,
        scale: 0.5,
        width: window.innerWidth,
        height: window.innerHeight,
      });

      // Convert to data URL. Keeping this synchronous avoids errors thrown
      // inside HTMLCanvasElement.toBlob callbacks bypassing the catch above.
      const format = message.format || 'jpeg';
      const quality = message.quality || 0.85;
      const mimeType = `image/${format}`;
      const dataUrl = canvas.toDataURL(mimeType, quality);

      window.parent.postMessage({
        type: 'vly-screenshot-response',
        requestId: message.requestId,
        dataUrl,
      } as ScreenshotMessage, '*');

    } catch (error) {

      window.parent.postMessage({
        type: 'vly-screenshot-error',
        requestId: message.requestId,
        error: error instanceof Error ? error.message : 'Unknown error',
      } as ScreenshotMessage, '*');
    }
  });
}
